export interface BaseRecord {
  id: string;
  createdAt: string;
  updatedAt: string;
}

export const RESUME_STATUSES = [
  "ready",
  "extraction-failed",
  "needs-review",
  "deleted",
] as const;
export type ResumeStatus = (typeof RESUME_STATUSES)[number];

export const INTERVIEW_STATUSES = [
  "scheduled",
  "completed",
  "cancelled",
  "rescheduled",
] as const;
export type InterviewStatus = (typeof INTERVIEW_STATUSES)[number];

export const STAGE_KINDS = [
  "normal",
  "offer",
  "rejected",
  "withdrawn",
] as const;
export type StageKind = (typeof STAGE_KINDS)[number];

export interface Resume extends BaseRecord {
  name: string;
  type: "pdf" | "docx";
  fileName: string;
  fileSize: number;
  fileHash: string;
  uploadedAt: string;
  tags: string[];
  note: string;
  status: ResumeStatus;
  textSource?: "extracted" | "manual";
  textConfirmedAt?: string;
  originalFileId?: string;
}

export type ResumeTextKind = "extracted" | "confirmed" | "manual";

export interface ResumeText extends BaseRecord {
  resumeId: string;
  kind: ResumeTextKind;
  text: string;
  confirmedAt?: string;
}

export interface JobDescription extends BaseRecord {
  applicationId: string;
  fileName?: string;
  fileType?: "pdf" | "docx";
  fileSize?: number;
  fileHash?: string;
  textSource: "pasted" | "extracted" | "manual";
  textConfirmedAt?: string;
  originalFileId?: string;
}

export type JobDescriptionTextKind =
  | "pasted"
  | "extracted"
  | "confirmed"
  | "manual";

export interface JobDescriptionText extends BaseRecord {
  jobDescriptionId: string;
  kind: JobDescriptionTextKind;
  text: string;
  confirmedAt?: string;
}

export interface Application extends BaseRecord {
  company: string;
  position: string;
  jobType: "graduate" | "internship" | "tech" | "general" | "other";
  location: string;
  workMode: "onsite" | "remote" | "hybrid" | "unknown";
  salaryText: string;
  source: string;
  jobUrl: string;
  jdText: string;
  jdFileId?: string;
  currentResumeId?: string;
  stageId: string;
  priority: number;
  deadline?: string;
  contact: string;
  note: string;
  archivedAt?: string;
}

export interface ResumeUsageHistory extends BaseRecord {
  applicationId: string;
  resumeId: string;
  resumeNameSnapshot: string;
  textSnapshot: string;
  usedAt: string;
}

export interface Stage extends BaseRecord {
  name: string;
  color: string;
  order: number;
  kind: StageKind;
}

export type TimelineEventType =
  | "stage-changed"
  | "resume-changed"
  | "note-added"
  | "archived"
  | "interview-rescheduled";

export interface ApplicationTimelineEvent extends BaseRecord {
  applicationId: string;
