} from "../../db/types";

export interface ApplicationServiceDependencies {
  now?: () => string;
  createId?: () => string;
}

export type CreateApplicationInput = Omit<
  Application,
  | "id"
  | "createdAt"
  | "updatedAt"
  | "currentResumeId"
  | "archivedAt"
  | "jdFileId"
  | "jdText"
> & {
  jdText?: string;
};

export type UpdateApplicationInput = Partial<
  Pick<
    Application,
    | "company"
    | "position"
    | "jobType"
    | "location"
    | "workMode"
    | "salaryText"
    | "source"
    | "jobUrl"
    | "deadline"
    | "contact"
    | "priority"
    | "note"
  >
>;

