export interface DomainRecordMap {
  resumes: Resume;
  resumeTexts: ResumeText;
  jobDescriptions: JobDescription;
  jobDescriptionTexts: JobDescriptionText;
  applications: Application;
  resumeUsageHistory: ResumeUsageHistory;
  stages: Stage;
  applicationTimelineEvents: ApplicationTimelineEvent;
  interviews: Interview;
  interviewReviews: InterviewReview;
  analysisResults: AnalysisResult;
  aiConversations: AiConversation;
  reminderFailures: ReminderFailure;
  originalFiles: StoredFile;
}

export type DomainStoreName = keyof DomainRecordMap;

import { afterEach, describe, expect, it, vi } from "vitest";

import { createApp } from "../src/app/createApp";

describe("application startup", () => {
  afterEach(() => {
    document.body.innerHTML = "";
    vi.unstubAllGlobals();
  });

  it("renders a perceptible local-ready state without an HTTP request", () => {
    const fetchSpy = vi.fn();
    vi.stubGlobal("fetch", fetchSpy);
    document.body.innerHTML = '<div id="app"></div>';

    const root = createApp(document);

    expect(root.querySelector("h1")?.textContent).toBe("求职工作台");
    expect(root.querySelector('[role="status"]')?.textContent).toContain(
      "本地数据已就绪",
    );
    expect(root.textContent).toContain("0 份简历");
    expect(root.textContent).toContain("0 个职位");
    expect(fetchSpy).not.toHaveBeenCalled();
  });

  it("rejects startup when the application root is missing", () => {
    expect(() => createApp(document)).toThrowError("找不到应用挂载节点 #app");
  });
});

