  const form = root.querySelector<HTMLFormElement>("form")!; const status = root.querySelector<HTMLElement>("[data-review-status]")!; let interviewId = options.interviewId; let lastSaved: InterviewReview | undefined;
  const field = (name: string) => root.querySelector<HTMLInputElement | HTMLTextAreaElement>(`[data-review-field="${name}"]`)!;
  const clear = () => { form.reset(); lastSaved = undefined; status.textContent = interviewId ? "待复盘" : "请选择面试"; };
  const apply = (review: InterviewReview) => { lastSaved = review; field("overallRating").value = review.overallRating === undefined ? "" : String(review.overallRating); field("questions").value = review.questions.map((item) => item.question).join("\n"); field("answers").value = review.questions.map((item) => item.answer ?? "").join("\n"); field("questionNotes").value = review.questions.map((item) => item.note ?? "").join("\n"); for (const name of ["goodAnswers", "weakAnswers", "observedSignals", "salaryDiscussion", "nextStep", "privateNote"] as const) field(name).value = review[name]; status.textContent = "已复盘"; };
  const load = async () => { clear(); if (!interviewId || !options.reviewService) return; const review = await options.reviewService.getReview(interviewId); if (review) apply(review); };
  root.addEventListener("interview-selected", (event) => { interviewId = (event as CustomEvent<string>).detail; void load(); });
  form.addEventListener("submit", async (event) => { event.preventDefault(); if (!interviewId || !options.reviewService) { status.textContent = "请先从日历选择一场面试"; return; } try { const questions = lines(field("questions").value); const answers = field("answers").value.split("\n"); const notes = field("questionNotes").value.split("\n"); const questionItems: ReviewQuestion[] = questions.map((question, index) => ({ question, ...(answers[index]?.trim() ? { answer: answers[index].trim() } : {}), ...(notes[index]?.trim() ? { note: notes[index].trim() } : {}) })); const saved = await options.reviewService.saveReview(interviewId, { overallRating: field("overallRating").value ? Number(field("overallRating").value) : undefined, questions: questionItems, goodAnswers: field("goodAnswers").value, weakAnswers: field("weakAnswers").value, observedSignals: field("observedSignals").value, salaryDiscussion: field("salaryDiscussion").value, nextStep: field("nextStep").value, privateNote: field("privateNote").value }); apply(saved); status.textContent = "复盘已保存 · 已复盘"; } catch (error) { status.textContent = error instanceof Error ? error.message : "复盘保存失败"; } });
  root.querySelector('[data-action="cancel-review"]')?.addEventListener("click", () => { if (lastSaved) apply(lastSaved); else clear(); status.textContent = lastSaved ? "已取消编辑，已保存数据未改变" : "已取消编辑，仍待复盘"; });
  void load(); return root;
}
