type InterviewInput = Omit<Interview, "id" | "createdAt" | "updatedAt" | "status"> & { status?: Interview["status"] };

export interface InterviewCalendarOptions {
  interviewService?: {
    listInterviews(applicationId?: string): Promise<Interview[]>;
